import _extends from "@babel/runtime/helpers/esm/extends";
import { styled } from '@mui/material/styles';
import { axisClasses } from '../../ChartsAxis/axisClasses';
export const AxisRoot = styled('g', {
  name: 'MuiChartsAxis',
  slot: 'Root',
  overridesResolver: (props, styles) => styles.root
})({
  [`&.${axisClasses.directionY}`]: {
    [`.${axisClasses.tickLabel}`]: {
      alignmentBaseline: 'middle'
    },
    [`.${axisClasses.label}`]: {
      alignmentBaseline: 'baseline',
      textAnchor: 'middle'
    }
  },
  [`&.${axisClasses.left}`]: {
    [`.${axisClasses.tickLabel}`]: {
      alignmentBaseline: 'central',
      textAnchor: 'end'
    }
  },
  [`&.${axisClasses.right}`]: {
    [`.${axisClasses.tickLabel}`]: {
      alignmentBaseline: 'central',
      textAnchor: 'start'
    }
  },
  [`&.${axisClasses.bottom}`]: {
    [`.${axisClasses.tickLabel}, .${axisClasses.label}`]: {
      alignmentBaseline: 'hanging',
      textAnchor: 'middle'
    }
  },
  [`&.${axisClasses.top}`]: {
    [`.${axisClasses.tickLabel}, .${axisClasses.label}`]: {
      alignmentBaseline: 'baseline',
      textAnchor: 'middle'
    }
  }
});
export const Line = styled('line', {
  name: 'MuiChartsAxis',
  slot: 'Line',
  overridesResolver: (props, styles) => styles.line
})(({
  theme
}) => ({
  stroke: theme.palette.text.primary,
  shapeRendering: 'crispEdges',
  strokeWidth: 1
}));
export const Tick = styled('line', {
  name: 'MuiChartsAxis',
  slot: 'Tick',
  overridesResolver: (props, styles) => styles.tick
})(({
  theme
}) => ({
  stroke: theme.palette.text.primary,
  shapeRendering: 'crispEdges'
}));
export const TickLabel = styled('text', {
  name: 'MuiChartsAxis',
  slot: 'TickLabel',
  overridesResolver: (props, styles) => styles.tickLabel
})(({
  theme
}) => _extends({}, theme.typography.caption, {
  fill: theme.palette.text.primary
}));
export const Label = styled('text', {
  name: 'MuiChartsAxis',
  slot: 'Label',
  overridesResolver: (props, styles) => styles.label
})(({
  theme
}) => _extends({}, theme.typography.body1, {
  fill: theme.palette.text.primary
}));
